// Store settings, complete catalog editing and quotation assistance.
const defaultStoreSettings={email:{enabled:false,fromName:'Power Electronics',fromEmail:'support@powerelectronics.demo',replyTo:'support@powerelectronics.demo'},sms:{enabled:false,sender:'POWER',adminPhone:''},adminEmail:'admin@powerelectronics.demo',payments:{upi:{enabled:true,fixed:0,percent:0},card:{enabled:true,fixed:0,percent:0},cod:{enabled:true,fixed:0,percent:0}}};
let storeSettings=read('store-settings',defaultStoreSettings),deliveryLog=read('delivery-log',[]),versionQuery='',versionCategory='',versionExpanded=new Set(),productImageDraft=null,quotationMatches={};
const paymentLabels={upi:'UPI',card:'Card',cod:'Cash on delivery'};
const paymentValues={upi:'Demo UPI',card:'Demo card',cod:'Demo cash on delivery'};
function configuredPayments(){return Object.entries(paymentValues).filter(([key])=>storeSettings.payments[key]?.enabled)}
function validPaymentMethod(value){return configuredPayments().some(([,v])=>v===value)}
function paymentKey(value){return Object.keys(paymentValues).find(k=>paymentValues[k]===value)}
function paymentFee(value,base){const key=paymentKey(value),p=storeSettings.payments[key];if(!p?.enabled)return 0;return Math.round((Number(p.fixed)+Math.max(0,base)*Number(p.percent)/100)*100)/100}
function selectedPayment(){return validPaymentMethod(checkoutDraft.payment)?checkoutDraft.payment:configuredPayments()[0]?.[1]||''}
function saveStoreSettings(data){requireDemoAdmin();const emailValid=v=>/^\S+@\S+\.\S+$/.test(v);const next=structuredClone(defaultStoreSettings);next.adminEmail=String(data.adminEmail||'').trim();next.email={enabled:data.emailEnabled==='on',fromName:String(data.fromName||'').trim().slice(0,100),fromEmail:String(data.fromEmail||'').trim(),replyTo:String(data.replyTo||'').trim()};if(!next.email.fromName||![next.adminEmail,next.email.fromEmail,next.email.replyTo].every(emailValid))throw Error('Provide valid admin, sender and reply-to email addresses.');next.sms={enabled:data.smsEnabled==='on',sender:String(data.smsSender||'').trim().slice(0,30),adminPhone:validateAlternatePhone(data.adminPhone)};if(next.sms.enabled&&(!next.sms.sender||!next.sms.adminPhone))throw Error('Provide an SMS sender and admin phone when enabling SMS.');for(const key of Object.keys(paymentValues)){const fixed=Number(data[key+'Fixed']),percent=Number(data[key+'Percent']);if(!Number.isFinite(fixed)||fixed<0||fixed>100000||!Number.isFinite(percent)||percent<0||percent>100)throw Error('Payment charges must be ₹0–₹1,00,000 and 0–100%.');next.payments[key]={enabled:data[key+'Enabled']==='on',fixed,percent}}if(!Object.values(next.payments).some(p=>p.enabled))throw Error('Keep at least one payment method enabled.');persistRecords({'store-settings':next});storeSettings=next;return next}
function settingsPage(){if(user?.role!=='admin')return admin();const s=storeSettings;return importLayout(`${opsHeading('Store configuration','Settings','Manage communication preferences and checkout payment options.')}<form id="storesettingsform"><div class="settings-grid"><section class="panel"><div class="settings-section-head"><span class="settings-symbol">${icon('support')}</span><div><h3>Email settings</h3><p>Quotation, stock and order updates</p></div><label class="switch-label"><input name="emailEnabled" type="checkbox" ${s.email.enabled?'checked':''}>Enabled</label></div><div class="form-grid">${field('Sender name','fromName',s.email.fromName,'text',true)}${field('Sender email','fromEmail',s.email.fromEmail,'email',true)}${field('Reply-to email','replyTo',s.email.replyTo,'email',true)}${field('Admin notification email','adminEmail',s.adminEmail,'email',true)}</div><small class="subtle">Email delivery is simulated in this demo. In-app notifications remain available.</small></section><section class="panel"><div class="settings-section-head"><span class="settings-symbol">${icon('user')}</span><div><h3>SMS settings</h3><p>Short status and availability updates</p></div><label class="switch-label"><input name="smsEnabled" type="checkbox" ${s.sms.enabled?'checked':''}>Enabled</label></div><div class="form-grid">${field('Sender / display ID','smsSender',s.sms.sender,'text')}${field('Admin phone number','adminPhone',s.sms.adminPhone,'tel',false,'[0-9+ ()-]{10,18}')}</div><small class="subtle">SMS delivery is simulated. No provider credentials are stored in this browser.</small></section></div><section class="panel payment-settings"><div class="section-head"><div><h3>Payment options & charges</h3><p>Choose available methods and their checkout fees.</p></div><span class="demo-pill">Demo checkout</span></div><div class="payment-settings-grid">${Object.keys(paymentValues).map(key=>{const m=s.payments[key];return `<div class="payment-setting-card"><label class="switch-label"><input name="${key}Enabled" type="checkbox" ${m.enabled?'checked':''}><b>${paymentLabels[key]}</b></label><label class="field">Fixed charge (₹)<input name="${key}Fixed" type="number" min="0" max="100000" step="0.01" value="${m.fixed}" required></label><label class="field">Percentage charge (%)<input name="${key}Percent" type="number" min="0" max="100" step="0.01" value="${m.percent}" required></label><small>Fixed fee + percentage of the discounted item subtotal. Delivery is excluded.</small></div>`}).join('')}</div></section><div class="settings-save"><p class="error" role="alert"></p><button class="btn">Save settings</button><span>Changes apply to future demo checkouts.</span></div></form><section class="panel delivery-log"><div class="section-head"><div><h3>Communication preview log</h3><p>Events generated after enabling email or SMS.</p></div></div>${deliveryLog.length?`<div class="table-scroll"><table class="data-table"><thead><tr><th>Channel</th><th>Recipient</th><th>Update</th><th>Time</th><th>Status</th></tr></thead><tbody>${deliveryLog.slice(0,50).map(d=>`<tr><td>${esc(d.channel)}</td><td>${esc(d.recipient)}</td><td>${esc(d.title)}</td><td>${dateLabel(d.at)}</td><td><span class="workflow-pill request-reviewing">Demo preview</span></td></tr>`).join('')}</tbody></table></div>`:'<p class="subtle">No previews yet. Enable a channel and create or update a request to see a preview.</p>'}</section>`,'settings')}
// Preview communication preferences without sending messages to external services.
const originalAddNotification=addNotification;
addNotification=function(recipient,type,title,message,link,entityId=''){originalAddNotification(recipient,type,title,message,link,entityId);let email='',phone='';if(recipient==='admin'){email=storeSettings.adminEmail;phone=storeSettings.sms.adminPhone}else if(recipient.startsWith('customer:')){const owner=recipient.slice(9),record=bulkOrders.find(o=>o.id===entityId)||stockRequests.find(r=>r.id===entityId);email=record?.email||owner;phone=record?.phone|| (owner===profile.email?profile.phone:'')}if(storeSettings.email.enabled&&email)deliveryLog.unshift({id:crypto.randomUUID(),channel:'Email',recipient:email,title,message,at:stamp(),status:'Demo preview'});if(storeSettings.sms.enabled&&phone)deliveryLog.unshift({id:crypto.randomUUID(),channel:'SMS',recipient:phone,title,message,at:stamp(),status:'Demo preview'})};
const priorWorkspaceTransaction=workspaceTransaction;
workspaceTransaction=function(action){const previous=structuredClone(deliveryLog);try{return priorWorkspaceTransaction(()=>{const result=action();persistRecords({'delivery-log':deliveryLog});return result})}catch(error){deliveryLog=previous;try{persistRecords({'delivery-log':previous})}catch{}throw error}};
const originalTotals=totals;
totals=function(){const t=originalTotals(),fee=route().path==='/checkout'?paymentFee(selectedPayment(),t.subtotal-t.discount):0;return {...t,paymentFee:fee,total:Math.round((t.total+fee)*100)/100}};
const originalSummary=summary;
summary=function(isCheckout=false){let html=originalSummary(isCheckout);if(isCheckout){const t=totals();html=html.replace('<div class="summary-line total">',`<div class="summary-line"><span>${paymentLabels[paymentKey(selectedPayment())]||'Payment'} charge</span><span>${t.paymentFee?money(t.paymentFee):'No charge'}</span></div><div class="summary-line total">`)}return html};
const originalCheckout=checkout;
checkout=function(){checkoutDraft.payment=selectedPayment();let html=originalCheckout();const start=html.indexOf('<div class="payment-options">'),end=html.indexOf('<label class="filter-choice"><input type="checkbox" name="acknowledge"',start);if(start>=0&&end>start){const base=originalTotals(),options=configuredPayments();const content=`<div class="payment-options">${options.map(([key,value])=>`<label class="payment-option"><input type="radio" name="payment" value="${value}" ${selectedPayment()===value?'checked':''}><span><b>${paymentLabels[key]} — demo</b><br><small>${paymentFee(value,base.subtotal-base.discount)?`Payment charge: ${money(paymentFee(value,base.subtotal-base.discount))}`:'No additional payment charge'} · No real payment is collected.</small></span></label>`).join('')}</div>`;html=html.slice(0,start)+content+html.slice(end)}return html};
function withActiveCatalog(fn){const all=products;try{products=all.filter(p=>p.active!==false);return fn()}finally{products=all}}
const originalHome=home,originalShop=shop,originalCard=card,originalDetail=detail;
home=function(){const hiddenHero=product(2)?.active===false,hiddenSide=product(4)?.active===false;let html=withActiveCatalog(()=>originalHome());if(hiddenHero)html=html.replace(/<div class="hero-art">[\s\S]*?<\/div><\/section>/,'<div class="hero-art"><div class="art-label"><strong>Build your next idea</strong>Explore the active catalog.</div></div></section>');if(hiddenSide)html=html.replace(/<section class="hero-side">[\s\S]*?<\/section>/,'<section class="hero-side"><div class="eyebrow">For your next project</div><h2>Explore your building blocks.</h2><p>Discover components from our active catalog.</p><a href="#/shop" class="btn">Shop components</a></section>');return html};
shop=function(q){return withActiveCatalog(()=>originalShop(q))};
card=function(p){return !p||p.active===false?'':originalCard(p)};
detail=function(id){if(product(id)?.active===false)return `<div class="wrap">${crumbs('Product')}${empty('This product is unavailable','Explore the active products in our catalog.')}</div>`;return originalDetail(id)};
function validateProductRecord(data,id){const p=product(id);if(!p)throw Error('Product not found.');const name=String(data.name||'').trim(),desc=String(data.description||'').trim(),sku=String(data.sku||'').trim().toUpperCase(),price=Number(data.price),old=Number(data.old),stock=Number(data.stock);if(!name||name.length>180||!desc||desc.length>2000)throw Error('Provide a title and description within the displayed limits.');if(!/^[A-Z0-9][A-Z0-9._-]{1,63}$/i.test(sku)||products.some(x=>x.id!==p.id&&(x.sku||`CT-${String(x.id).padStart(4,'0')}`).toUpperCase()===sku))throw Error('Enter a unique SKU (2–64 letters, numbers, dots, underscores or hyphens).');if(!categories.some(([c])=>c===data.category))throw Error('Select a supported category.');if(!Number.isFinite(price)||price<0.01||price>1000000||!Number.isFinite(old)||old<price)throw Error('Enter a positive selling price and a compare-at price no lower than it.');if(!Number.isInteger(stock)||stock<0||stock>100000)throw Error('Stock must be a whole number from 0 to 1,00,000.');const imageUrl=String(data.imageUrl||'').trim(),assetId=Number(data.assetId)||p.assetId||p.id;if(imageUrl&&!safeImageUrl(imageUrl))throw Error('Use a public HTTPS image URL.');const specs={};for(const line of String(data.specifications||'').split('\n').filter(l=>l.trim())){const index=line.indexOf(':');if(index<1)throw Error('Write each specification as Label: Value on its own line.');const key=line.slice(0,index).trim(),value=line.slice(index+1).trim();if(!value||key.length>100||value.length>500||Object.keys(specs).length>=30)throw Error('Use up to 30 specifications with a label and value.');specs[key]=value}return {id:p.id,name,desc,sku,category:data.category,price,old,stock,active:data.active==='true',assetId,imageUrl,imageData:productImageDraft!==null?productImageDraft:(!imageUrl&&assetId===(p.assetId||p.id)?p.imageData:'')||'',specs}}
function productEditor(id){requireDemoAdmin();const p=product(id);if(!p)throw Error('Product not found.');productImageDraft=null;showModal(`<div class="eyebrow">Catalog editor</div><h2>Edit product</h2><p>Update all customer-facing details and catalog visibility.</p><form id="catalogeditform" data-id="${p.id}"><div class="form-grid">${field('Product title','name',p.name,'text',true)}${field('SKU','sku',p.sku||'CT-'+String(p.id).padStart(4,'0'),'text',true)}<label class="field">Category<select name="category">${categories.map(([c])=>`<option ${p.category===c?'selected':''}>${esc(c)}</option>`).join('')}</select></label><label class="field">Visibility<select name="active"><option value="true" ${p.active!==false?'selected':''}>Active — visible in store</option><option value="false" ${p.active===false?'selected':''}>Inactive — hidden from store</option></select></label><label class="field full">Description<textarea name="description" rows="3" maxlength="2000" required>${esc(p.desc)}</textarea></label>${field('Selling price (₹)','price',p.price,'number',true)}${field('Compare-at price (₹)','old',p.old,'number',true)}${field('Available units','stock',p.stock,'number',true)}<label class="field">Reference image<select name="assetId">${baseProducts.map(x=>`<option value="${x.id}" ${Number(p.assetId||p.id)===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label><label class="field full">Image URL (op)<input type="url" name="imageUrl" value="${esc(p.imageData?'':p.imageUrl||'')}" placeholder="https://…"></label><label class="field full">Upload replacement image (op)<input type="file" id="catalogimagefile" accept="image/png,image/jpeg,image/webp"><small>PNG, JPEG or WebP · Maximum 500 KB. Upload takes priority over the URL.</small></label><div class="editor-image-preview full"><img id="catalogimagepreview" src="${p.imageData||img(p.id)}" alt="Product image preview"><span id="catalogimagestatus">Current product image</span><button type="button" class="text-link" data-admin-feature="reset-image">Use selected reference photo</button></div><label class="field full">Specifications<textarea name="specifications" rows="5" maxlength="18000" placeholder="Voltage: 5V">${esc(Object.entries(p.specs||{}).map(([k,v])=>k+': '+v).join('\n'))}</textarea><small>One Label: Value per line, up to 30 specifications.</small></label></div><p class="error" role="alert"></p><div class="import-editor-actions"><button class="btn">Save product</button><button type="button" class="btn btn-outline" data-admin-feature="product-versions" data-id="${p.id}">View price versions</button></div></form>`);$('#modal').classList.add('operations-modal');for(const key of ['price','old','stock']){const input=$(`#catalogeditform [name="${key}"]`);input.min=key==='stock'?0:0.01;input.step=key==='stock'?1:0.01}$('#catalogeditform [name="name"]').maxLength=180}
editProduct=productEditor;
async function readProductImage(file){if(!file)throw Error('Choose an image.');if(file.size>500*1024)throw Error('Maximum image size is 500 KB.');const bytes=new Uint8Array(await file.arrayBuffer()),png=bytes[0]===137&&bytes[1]===80&&bytes[2]===78&&bytes[3]===71,jpeg=bytes[0]===255&&bytes[1]===216&&bytes[2]===255,webp=String.fromCharCode(...bytes.slice(0,4))==='RIFF'&&String.fromCharCode(...bytes.slice(8,12))==='WEBP';if(!png&&!jpeg&&!webp)throw Error('Choose a valid PNG, JPEG or WebP image.');return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('Image could not be read.'));reader.readAsDataURL(new Blob([bytes],{type:png?'image/png':jpeg?'image/jpeg':'image/webp'}))})}
async function saveFullProduct(id,data){requireDemoAdmin();const record=validateProductRecord(data,id);if(record.imageUrl&&!record.imageData){const draft={imageUrl:record.imageUrl};await verifyDraftImage(draft);if(draft.imageStatus!=='verified')throw Error('The image URL could not be loaded. Choose a reference photo or upload an image.')}requireDemoAdmin();commitProductChanges([record],'Full product edit');return product(id)}
function toggleProductActive(id){requireDemoAdmin();const p=product(id);if(!p)throw Error('Product not found.');commitProductChanges([{id:p.id,active:p.active===false}],'Catalog visibility update')}
function versionRows(p){const changes=priceHistory.filter(h=>h.productId===p.id).slice().reverse();if(!changes.length)return [{version:1,price:p.price,at:null,reason:'Current catalog price',actor:'—'}];return [{version:1,price:changes[0].before,at:null,reason:'Initial recorded price',actor:'—'},...changes.map((h,i)=>({version:i+2,price:h.after,at:h.at,reason:h.reason,actor:h.actor,before:h.before}))]}
function priceVersionTree(list,forceExpanded=false){return `<div class="table-scroll"><table class="data-table price-tree" role="treegrid" aria-label="Product price versions"><thead><tr><th>Product / version</th><th>Price</th><th>Change</th><th>Reason</th><th>When / admin</th></tr></thead><tbody>${list.map(p=>{const rows=versionRows(p),expanded=forceExpanded||versionExpanded.has(p.id);return `<tr class="version-product" role="row" aria-level="1" aria-expanded="${expanded}"><td><button class="version-toggle" data-admin-feature="expand-versions" data-id="${p.id}" aria-label="${expanded?'Collapse':'Expand'} price versions for ${esc(p.name)}">${expanded?'▾':'▸'}</button><b>${esc(p.name)}</b><small>${esc(p.sku||'CT-'+String(p.id).padStart(4,'0'))} · ${rows.length} versions · ${p.active===false?'Inactive':'Active'}</small></td><td><b>${money(p.price)}</b></td><td colspan="3"><span class="subtle">Current catalog price</span></td></tr>${expanded?rows.slice().reverse().map(r=>`<tr role="row" aria-level="2" class="version-child"><td><span class="version-branch"></span> Version ${r.version}${r.version===rows.length?'<span class="current-version">Latest</span>':''}</td><td>${money(r.price)}</td><td>${r.before===undefined?'—':`${r.price>=r.before?'+':''}${money(r.price-r.before)}`}</td><td>${esc(r.reason)}</td><td>${r.at?dateLabel(r.at):'Initial record'}<small>${esc(r.actor)}</small></td></tr>`).join(''):''}`}).join('')}</tbody></table></div>`}
priceHistoryPage=function(){if(user?.role!=='admin')return admin();const term=versionQuery.toLowerCase(),list=products.filter(p=>(!versionCategory||p.category===versionCategory)&&(!term||`${p.name} ${p.sku||''} ${p.category} ${priceHistory.filter(h=>h.productId===p.id).map(h=>h.name+' '+h.reason+' '+h.actor+' '+h.before+' '+h.after).join(' ')}`.toLowerCase().includes(term)));return importLayout(`${opsHeading('Catalog audit trail','Price versions','Expand each product to see its complete recorded price history.','<a class="btn btn-outline" href="#/admin/pricing">Manage pricing</a>')}<section class="panel"><div class="version-toolbar"><input id="versionsearch" aria-label="Search product price versions" value="${esc(versionQuery)}" placeholder="Search product, SKU, reason or admin"><select data-admin-filter="version-category" aria-label="Filter price versions by category"><option value="">All categories</option>${categories.map(([c])=>`<option ${versionCategory===c?'selected':''}>${esc(c)}</option>`).join('')}</select><button class="btn btn-outline btn-small" data-admin-feature="expand-all">Expand all</button><button class="btn btn-outline btn-small" data-admin-feature="collapse-all">Collapse all</button><button class="btn btn-outline btn-small" data-ops="export-history">Export changes</button></div><div class="section-head"><h3>${list.length} products</h3><span class="subtle">${priceHistory.length} recorded changes</span></div>${list.length?priceVersionTree(list):'<div class="import-empty"><h3>No versions match your search.</h3></div>'}</section>`,'history')};
const originalCalculatePricePreview=calculatePricePreview;
calculatePricePreview=function(data){if(data.type!=='outofstock')return originalCalculatePricePreview(data);requireDemoAdmin();let target;if(data.scope==='all')target=products;else if(data.scope==='category'){if(!pricingCategory)throw Error('Select a category first.');target=products.filter(p=>p.category===pricingCategory)}else if(data.scope==='selected')target=products.filter(p=>pricingSelection.has(p.id));else throw Error('Select an adjustment scope.');if(!target.length)throw Error('No products selected.');if(!String(data.reason||'').trim())throw Error('Add a reason for the inventory update.');return {operation:'outofstock',rows:target.map(p=>({id:p.id,name:p.name,before:p.stock,after:0})),reason:String(data.reason).trim().slice(0,180)}};
const originalShowPricePreview=showPricePreview;
showPricePreview=function(data){if(data.type!=='outofstock')return originalShowPricePreview(data);pricingPreview=calculatePricePreview(data);showModal(`<div class="eyebrow">Review inventory action</div><h2>Mark ${pricingPreview.rows.length} products out of stock?</h2><p>${esc(pricingPreview.reason)}</p><div class="table-scroll bulk-preview-table"><table class="data-table"><thead><tr><th>Product</th><th>Current units</th><th>New units</th></tr></thead><tbody>${pricingPreview.rows.map(r=>`<tr><td>${esc(r.name)}</td><td>${r.before}</td><td>0 · Out of stock</td></tr>`).join('')}</tbody></table></div><p>Prices remain unchanged. These products remain visible and customers can request availability.</p><button class="btn" data-admin-feature="apply-outofstock">Save out-of-stock update</button>`)};
function normalizeItemText(v){return String(v).toLowerCase().replace(/[^a-z0-9]/g,'')}
function recommendedQuotation(o){const manual=quotationMatches[o.id]||{},rows=o.items.map((item,index)=>{const available=products.filter(p=>p.active!==false);let match=manual[index]!==undefined?available.find(p=>p.id===Number(manual[index])):null;if(manual[index]===undefined){const key=normalizeItemText(item.item),exact=available.filter(p=>[p.name,p.sku||'CT-'+String(p.id).padStart(4,'0')].some(v=>normalizeItemText(v)===key));if(exact.length===1)match=exact[0]}return {index,item:item.item,count:item.count,product:match||null,unitPrice:match?.price??null,lineTotal:match?Math.round(match.price*item.count*100)/100:null}});return {rows,complete:rows.every(r=>r.product),total:Math.round(rows.reduce((a,r)=>a+(r.lineTotal||0),0)*100)/100}}
function quotationProposal(o){const result=recommendedQuotation(o);return `<section id="quotationproposal" class="quotation-proposal"><div class="section-head"><div><div class="eyebrow">Quotation assistant</div><h3>Recommended quotation</h3></div><span class="recommended-total">${money(result.total)}${result.complete?'':' · Partial'}</span></div><p>Current catalog unit price × requested quantity. Delivery and payment charges are excluded. Check availability before committing a delivery date.</p><div class="table-scroll"><table class="data-table"><thead><tr><th>Requested component / catalog match</th><th>Qty</th><th>Unit price</th><th>Total</th></tr></thead><tbody>${result.rows.map(r=>`<tr><td><b>${esc(r.item)}</b><select data-quotation-match="${r.index}" data-order-id="${o.id}" aria-label="Match ${esc(r.item)} to a product"><option value="">Choose product</option>${products.filter(p=>p.active!==false).map(p=>`<option value="${p.id}" ${r.product?.id===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select><small class="${r.product?'check':'out'}">${r.product?r.product.stock>=r.count?'Quantity in stock':'Stock needs confirmation':'Unmatched — select a component'}</small></td><td>${r.count}</td><td>${r.product?money(r.unitPrice):'—'}</td><td>${r.product?money(r.lineTotal):'—'}</td></tr>`).join('')}</tbody></table></div><div class="quote-add-row"><span>${result.complete?'Do you want to add this amount to the quotation?':'Match every component to calculate a complete recommendation.'}</span><button type="button" class="btn" data-admin-feature="apply-quote" data-id="${o.id}" ${!result.complete?'disabled':''}>Add ${money(result.total)} quotation</button></div><small>Adding the amount fills the quotation field. Save the request update to notify the customer.</small></section>`}
const priorBulkDetail=bulkDetail;
bulkDetail=function(id){priorBulkDetail(id);const o=bulkOrders.find(o=>o.id===id);if(user?.role==='admin'&&o?.status!=='Completed')$('#modalcontent').innerHTML=$('#modalcontent').innerHTML.replace('<section class="status-update-panel">',quotationProposal(o)+'<section class="status-update-panel">')};
document.addEventListener('change',async e=>{try{if(e.target.name==='payment'&&e.target.closest?.('#checkoutform')){checkoutDraft=Object.fromEntries(new FormData($('#checkoutform')));render()}if(e.target.id==='catalogimagefile'){const button=$('#catalogeditform button');button.disabled=true;try{productImageDraft=await readProductImage(e.target.files[0]);if($('#catalogimagepreview')){$('#catalogimagepreview').src=productImageDraft;$('#catalogimagestatus').textContent='Replacement image ready'}}finally{if($('#catalogeditform button'))$('#catalogeditform button').disabled=false}}if(e.target.name==='type'&&e.target.closest?.('#priceadjustform')){const out=e.target.value==='outofstock';for(const name of ['amount','direction']){const input=$(`#priceadjustform [name="${name}"]`);input.disabled=out;if(name==='amount')input.required=!out}$('#priceadjustform button').textContent=out?'Preview stock update':'Preview price changes'}if(e.target.dataset.adminFilter==='version-category'){versionCategory=e.target.value;render()}if(e.target.dataset.quotationMatch!==undefined){const id=e.target.dataset.orderId;quotationMatches[id]??={};quotationMatches[id][Number(e.target.dataset.quotationMatch)]=e.target.value;$('#quotationproposal').outerHTML=quotationProposal(bulkOrders.find(o=>o.id===id))}}catch(error){toast(error.message)}});
document.addEventListener('input',e=>{if(e.target.id==='versionsearch'){versionQuery=e.target.value;const pos=e.target.selectionStart;render();$('#versionsearch').focus();$('#versionsearch').setSelectionRange(pos,pos)}});
document.addEventListener('submit',async e=>{const f=e.target;if(!['storesettingsform','catalogeditform'].includes(f.id))return;e.preventDefault();try{const data=Object.fromEntries(new FormData(f));if(f.id==='storesettingsform'){saveStoreSettings(data);render();toast('Store settings saved')}else{const button=f.querySelector('button');button.disabled=true;await saveFullProduct(f.dataset.id,data);productImageDraft=null;closeModal();render();toast('Product details saved')}}catch(error){f.querySelector('[role="alert"]').textContent=error.message;const button=f.querySelector('button');if(button)button.disabled=false}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-admin-feature]');if(!b)return;try{requireDemoAdmin();const action=b.dataset.adminFeature,id=Number(b.dataset.id);if(action==='reset-image'){productImageDraft='';$('#catalogeditform [name="imageUrl"]').value='';$('#catalogimagepreview').src='/assets/product-'+$('#catalogeditform [name="assetId"]').value+'.webp';$('#catalogimagestatus').textContent='Reference image selected'}else if(action==='toggle-active'){const p=product(id);showModal(`<h2>${p.active===false?'Activate':'Deactivate'} product?</h2><p>${esc(p.name)} ${p.active===false?'will become visible in the storefront.':'will be hidden from the storefront. It will remain in admin records and order history.'}</p><button class="btn" data-admin-feature="confirm-active" data-id="${id}">Confirm ${p.active===false?'activation':'deactivation'}</button>`)}else if(action==='confirm-active'){toggleProductActive(id);closeModal();render();toast('Product visibility updated')}else if(action==='product-versions'){showModal(`<div class="eyebrow">Product price history</div><h2>${esc(product(id).name)}</h2>${priceVersionTree([product(id)],true)}`);$('#modal').classList.add('operations-modal')}else if(action==='expand-versions'){if(versionExpanded.has(id))versionExpanded.delete(id);else versionExpanded.add(id);if(route().path==='/admin/price-history')render();else{showModal(`<h2>${esc(product(id).name)}</h2>${priceVersionTree([product(id)],true)}`)}}else if(action==='expand-all'){versionExpanded=new Set(products.map(p=>p.id));render()}else if(action==='collapse-all'){versionExpanded.clear();render()}else if(action==='apply-outofstock'){if(pricingPreview?.operation!=='outofstock')throw Error('Generate a stock update preview first.');if(pricingPreview.rows.some(r=>product(r.id)?.stock!==r.before))throw Error('Stock has changed. Generate a fresh preview.');commitProductChanges(pricingPreview.rows.map(r=>({id:r.id,stock:0})),pricingPreview.reason);pricingPreview=null;closeModal();render();toast('Products marked out of stock')}else if(action==='apply-quote'){const o=bulkOrders.find(o=>o.id===b.dataset.id),result=recommendedQuotation(o);if(!result.complete)throw Error('Match every requested item first.');$('#bulkmanageform [name="quote"]').value=result.total.toFixed(2);toast('Recommended amount added. Save the request update when ready.')}}catch(error){toast(error.message)}});
window.addEventListener('storage',e=>{if(e.key==='circuit-demo-store-settings'){storeSettings=read('store-settings',defaultStoreSettings);if(!$('#modal').open)render()}if(e.key==='circuit-demo-delivery-log')deliveryLog=read('delivery-log',[])});
